package ru.hollowhorizon.hollowengine.common.scripting.compiling

import org.objectweb.asm.ClassReader
import org.objectweb.asm.ClassVisitor
import org.objectweb.asm.Opcodes

/** Classes emitted for a script, including top-level classes generated by compiler plugins. */
object ScriptClassFiles {
    fun of(scriptClass: String, output: Map<String, ByteArray>): Map<String, ByteArray> {
        val prefix = scriptClass.replace('.', '/')
        val packagePath = prefix.substringBeforeLast('/', "")
        val source = output["$prefix.class"]?.let(::sourceFile)
        return output.filter { (path, bytes) ->
            path == "$prefix.class" || path.startsWith("$prefix$") ||
                (source != null && path.endsWith(".class") && path.substringBeforeLast('/', "") == packagePath &&
                    sourceFile(bytes) == source)
        }
    }

    private fun sourceFile(bytes: ByteArray): String? {
        var source: String? = null
        ClassReader(bytes).accept(object : ClassVisitor(Opcodes.ASM9) {
            override fun visitSource(sourceFile: String?, debug: String?) {
                source = sourceFile
            }
        }, ClassReader.SKIP_CODE or ClassReader.SKIP_FRAMES)
        return source
    }
}
